DROP TABLE IF EXISTS `customer_reports`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `customer_reports` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `customer_id` int(11) NOT NULL,
  `kitchen_id` int(11) NOT NULL,
  `order_id` int(11) DEFAULT NULL,
  `target_type` enum('kitchen','dish','delivery') NOT NULL,
  `target_id` int(11) DEFAULT NULL,
  `reason` varchar(100) NOT NULL,
  `description` text NOT NULL,
  `status` enum('pending','reviewed','resolved') DEFAULT 'pending',
  `admin_notes` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `resolved_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_cr_order_id` (`order_id`),
  KEY `idx_cr_customer_id` (`customer_id`),
  KEY `idx_cr_kitchen_id` (`kitchen_id`),
  KEY `idx_cr_target_type` (`target_type`),
  KEY `idx_cr_target_id` (`target_id`),
  KEY `idx_cr_status` (`status`),
  KEY `idx_cr_created_at` (`created_at`),
  KEY `idx_cr_kitchen_type` (`kitchen_id`,`target_type`),
  CONSTRAINT `customer_reports_ibfk_1` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`) ON DELETE CASCADE,
  CONSTRAINT `customer_reports_ibfk_2` FOREIGN KEY (`kitchen_id`) REFERENCES `kitchens` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_cr_order_id` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
