CREATE TABLE `customer_subscriptions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `customer_id` int(11) NOT NULL,
  `subscription_plan_id` int(11) NOT NULL,
  `kitchen_id` int(11) NOT NULL,
  `address_id` int(11) NOT NULL,
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `status` enum('pending','active','paused','cancelled','completed') DEFAULT 'pending',
  `payment_method` enum('cod','upi','card','netbanking','online') DEFAULT 'cod',
  `payment_status` enum('pending','completed','failed','refunded') DEFAULT 'pending',
  `total_paid` decimal(8,2) NOT NULL,
  `special_instructions` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `subscription_plan_id` (`subscription_plan_id`),
  KEY `address_id` (`address_id`),
  KEY `idx_sub_kitchen_id` (`kitchen_id`),
  KEY `idx_sub_customer_id` (`customer_id`),
  KEY `idx_sub_status` (`status`),
  CONSTRAINT `customer_subscriptions_ibfk_2` FOREIGN KEY (`subscription_plan_id`) REFERENCES `tiffin_subscriptions` (`id`),
  CONSTRAINT `customer_subscriptions_ibfk_3` FOREIGN KEY (`kitchen_id`) REFERENCES `kitchens` (`id`),
  CONSTRAINT `customer_subscriptions_ibfk_4` FOREIGN KEY (`address_id`) REFERENCES `addresses` (`id`),
  CONSTRAINT `fk_sub_cust` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`) ON DELETE CASCADE,
  CONSTRAINT `subs_customer_fk` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=30 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
