--
-- Table structure for table `delivery_users`
--

DROP TABLE IF EXISTS `delivery_users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `delivery_users` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `full_name` varchar(50) NOT NULL,
  `email` varchar(50) NOT NULL,
  `phone` char(10) NOT NULL,
  `city` varchar(100) DEFAULT NULL,
  `password_hash` varchar(60) NOT NULL,
  `role` enum('customer','chef','admin','delivery') NOT NULL DEFAULT 'customer',
  `status` enum('active','inactive','suspended','pending_verification') NOT NULL DEFAULT 'active',
  `email_verified` tinyint(1) NOT NULL DEFAULT 0,
  `email_otp_hash` varchar(255) DEFAULT NULL,
  `email_otp_expires_at` datetime DEFAULT NULL,
  `email_otp_resent_at` datetime DEFAULT NULL,
  `email_otp_attempts` tinyint(1) NOT NULL DEFAULT 0,
  `reset_otp_hash` varchar(60) DEFAULT NULL,
  `reset_otp_expires_at` datetime DEFAULT NULL,
  `reset_otp_resent_at` datetime DEFAULT NULL,
  `reset_otp_attempts` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`),
  UNIQUE KEY `phone` (`phone`),
  KEY `idx_user_role` (`role`)
) ENGINE=InnoDB AUTO_INCREMENT=217 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

