DROP TABLE IF EXISTS `order_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `order_items` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL,
  `menu_item_id` int(11) NOT NULL,
  `quantity` smallint(5) unsigned NOT NULL,
  `unit_price` decimal(6,2) NOT NULL,
  `subtotal` decimal(8,2) NOT NULL,
  `spice_level` enum('Low','Medium','High') DEFAULT 'Medium',
  `oil_level` enum('Normal','Less Oil') DEFAULT 'Normal',
  `is_jain` tinyint(1) DEFAULT 0,
  `item_notes` text DEFAULT NULL,
  `is_zero_waste` tinyint(1) NOT NULL DEFAULT 0,
  `zero_waste_id` int(10) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_oi_order_id` (`order_id`),
  KEY `idx_oi_menu_item_id` (`menu_item_id`),
  CONSTRAINT `order_items_ibfk_1` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE,
  CONSTRAINT `order_items_ibfk_2` FOREIGN KEY (`menu_item_id`) REFERENCES `menu_items` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=284 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

