--
-- Table structure for table `orders`
--

DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `orders` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_number` varchar(30) NOT NULL,
  `order_type` enum('standard','tiffin') NOT NULL DEFAULT 'standard',
  `subscription_delivery_id` int(11) DEFAULT NULL,
  `customer_id` int(11) NOT NULL,
  `kitchen_id` int(11) NOT NULL,
  `address_id` int(11) NOT NULL,
  `delivery_latitude` decimal(10,8) DEFAULT NULL,
  `delivery_longitude` decimal(11,8) DEFAULT NULL,
  `total_amount` decimal(8,2) NOT NULL,
  `payment_method` enum('cod','upi','card','netbanking','online') DEFAULT 'cod',
  `payment_status` enum('pending','completed','failed','refunded') DEFAULT 'pending',
  `razorpay_payment_id` varchar(50) DEFAULT NULL,
  `order_status` enum('pending','accepted','preparing','ready_for_pickup','out_for_delivery','delivered','cancelled','delivery_failed') DEFAULT 'pending',
  `delivery_partner_id` int(11) DEFAULT NULL,
  `offered_driver_id` int(11) DEFAULT NULL,
  `offer_expires_at` datetime DEFAULT NULL,
  `rejected_by_drivers` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`rejected_by_drivers`)),
  `delivery_otp` char(4) DEFAULT NULL,
  `delivery_status` enum('unassigned','assigned','accepted','picked_up','out_for_delivery','delivered','failed') DEFAULT 'unassigned',
  `delivery_accepted_at` datetime DEFAULT NULL,
  `delivery_picked_up_at` datetime DEFAULT NULL,
  `delivery_completed_at` datetime DEFAULT NULL,
  `delivery_failed_reason` varchar(255) DEFAULT NULL,
  `special_instructions` varchar(500) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `dispatch_status` enum('none','cascading','broadcasting','assigned','no_rider','manual') NOT NULL DEFAULT 'none',
  `dispatch_started_at` datetime DEFAULT NULL,
  `dispatch_round` tinyint(4) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `order_number` (`order_number`),
  KEY `address_id` (`address_id`),
  KEY `idx_kitchen_id` (`kitchen_id`),
  KEY `idx_customer_id` (`customer_id`),
  KEY `idx_order_status` (`order_status`),
  KEY `idx_created_at` (`created_at`),
  KEY `idx_orders_delivery` (`delivery_partner_id`),
  KEY `idx_orders_delivery_status` (`delivery_status`),
  CONSTRAINT `fk_order_cust` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`) ON DELETE CASCADE,
  CONSTRAINT `orders_ibfk_2` FOREIGN KEY (`kitchen_id`) REFERENCES `kitchens` (`id`),
  CONSTRAINT `orders_ibfk_3` FOREIGN KEY (`address_id`) REFERENCES `addresses` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=202 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

