INSERT INTO `reviews` VALUES (1,40,52,37,5,'Tastes exactly like my mom\'s cooking. Highly recommended!','2026-09-08 10:14:37'),(3,56,47,43,4,'Very tasty and authentic. The dosa was perfectly crispy. Will order again!','2026-09-16 06:29:21'),(4,58,47,43,5,'Fresh, hygienic, and tastes exactly like my mom\'s cooking. 5 stars easily!','2026-09-16 06:29:21'),(5,59,55,43,3,'Food was okay. Average taste but good hygiene. Could improve on spices.','2026-09-16 06:29:21'),(6,60,47,43,5,'Best home-cooked food I\'ve had outside my own home. Highly recommend!','2026-09-16 06:29:21'),(7,61,47,43,2,'Food was cold by the time it arrived. Taste was okay though.','2026-09-16 06:29:21'),(8,62,1,43,5,'Best home-cooked food I\'ve had outside my own home. Highly recommend!','2026-09-16 06:29:21'),(9,64,52,43,4,'Good food and good quantity. Nice packaging too.','2026-09-16 06:29:21'),(10,65,1,43,3,'Food was okay. Average taste but good hygiene. Could improve on spices.','2026-09-16 06:29:21'),(11,66,57,43,2,'Food was cold by the time it arrived. Taste was okay though.','2026-09-16 06:29:21'),(12,68,57,43,3,'Food was okay. Average taste but good hygiene. Could improve on spices.','2026-09-16 06:29:21'),(13,69,1,43,4,'Good food and good quantity. Nice packaging too.','2026-09-16 06:29:21'),(14,70,1,43,3,'Decent meal. Nothing extraordinary but served its purpose.','2026-09-16 06:29:21'),(15,71,1,43,4,'Really good food. Dal Makhani was rich and flavorful. Slightly late but worth it.','2026-09-16 06:29:21'),(17,73,55,43,5,'Fresh, hygienic, and tastes exactly like my mom\'s cooking. 5 stars easily!','2026-09-16 06:29:21'),(18,74,55,43,4,'Good food and good quantity. Nice packaging too.','2026-09-16 06:29:21'),(19,72,55,43,4,'The Food was Amazing !!!','2026-09-16 12:50:18'),(20,115,55,43,5,'wqdew','2026-10-03 09:41:44');
